// ── Shared helpers ──
// One source of truth for project data, used by portfolio.html, work-vd/dr/sms.html,
// index.html, and about.html. Add a new project here and it automatically appears
// everywhere: the orbit diagram, the relevant work subpage grids, the index.html
// splash gallery, and (if recent enough) the about.html carousel.

var PROJECT_ORDER = Object.keys(PROJECTS); // stable definition order, used as tiebreak

var MONTH_NAMES = { january:1, february:2, march:3, april:4, may:5, june:6, july:7, august:8, september:9, october:10, november:11, december:12 };

function getProjectRecencyScore(id, now) {
  var proj = PROJECTS[id];
  if (!proj) return 0;
  now = now || new Date();
  var years = (proj.tags.when || []).map(Number);
  if (!years.length) return 0;
  var maxYear = Math.max.apply(null, years);

  var whenMeta = proj.meta.filter(function(m) { return m.label === 'When?'; })[0];
  var text = (whenMeta ? whenMeta.value : '').toLowerCase();

  if (text.indexOf('present') >= 0 || text.indexOf('ongoing') >= 0) {
    var nowScore = now.getFullYear() * 12 + (now.getMonth() + 1);
    return Math.max(nowScore, maxYear * 12 + 12);
  }

  var re = new RegExp('(january|february|march|april|may|june|july|august|september|october|november|december)\\s+' + maxYear, 'i');
  var m = text.match(re);
  if (m) return maxYear * 12 + MONTH_NAMES[m[1].toLowerCase()];

  return maxYear * 12 + 12;
}

// Returns the N most recent project IDs, most recent first. Ties (e.g. multiple
// projects all currently "ongoing" with no month given) break by stable
// definition order in PROJECTS above, not randomly, so the result is
// consistent across page loads.
function getMostRecentProjectIds(n, now) {
  now = now || new Date();
  var scored = PROJECT_ORDER.map(function(id, i) {
    return { id: id, score: getProjectRecencyScore(id, now), i: i };
  });
  scored.sort(function(a, b) {
    if (b.score !== a.score) return b.score - a.score;
    return a.i - b.i;
  });
  return scored.slice(0, n).map(function(s) { return s.id; });
}

// Second image is used as the index.html splash thumbnail (falls back to the
// first image, then to nothing, if a project doesn't have a second image yet).
function getSecondImage(id) {
  var proj = PROJECTS[id];
  if (!proj || !proj.images || !proj.images.length) return '';
  return proj.images[1] || proj.images[0] || '';
}
